//! active: the counter is an island. The server renders the whole page with `Document`;
//! the browser bundle hydrates only the island.

use active::prelude::*;

/// Library name, which names the files generated by wasm-bindgen.
pub const LIB: &str = "counter_active";

/// The island: a button that increments the number next to it.
pub fn counter(props: &str) -> Node {
    let count = use_state(props.parse::<i32>().unwrap_or(0));
    fragment([
        button()
            .id("inc")
            .on_click(move |_| count.update(|n| *n += 1))
            .text("+1")
            .into(),
        Node::from(span().id("count").text_dyn(move || count.get().to_string())),
    ])
}

/// The server HTML.
#[cfg(not(target_arch = "wasm32"))]
pub fn page() -> String {
    use bench_common::{COUNTER_START, bundle_js, bundle_wasm};
    Document::new(island("counter", COUNTER_START.to_string(), counter))
        .lang("en")
        .seo(Seo::new().title("Counter"))
        .client(bundle_js(LIB), bundle_wasm(LIB))
        .render()
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    bench_common::mark("data-start");
    // Synchronous: listeners are attached when it returns.
    active::hydrate(&[("counter", counter)]);
    bench_common::mark("data-ready");
}
